import { useFormContext } from 'react-hook-form';
import { FormField, FormItem, FormLabel, FormControl, FormMessage } from '@/components/ui/form';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import CalendarIcon from '../icons/CalendarIcon';
import { cn } from '@/lib/utils';

interface Props {
    className?: string;
    name: string;
    label?: string;
    placeholder?: string;
}

export default function YearSelectForm({ className, name, label, placeholder }: Props) {
    const { control } = useFormContext();
    return (
        <FormField
            control={control}
            name={name}
            render={({ field }) => (
                <FormItem className={cn('flex flex-col justify-start', { className })}>
                    <FormLabel className="text-primery-blue-900 font-medium text-[18px] leading-[33.73px] tracking-normal text-start">
                        {label}
                    </FormLabel>
                    <Select
                        onValueChange={field.onChange}
                        value={
                            field.value != null && field.value !== ''
                                ? String(field.value)
                                : undefined
                        }
                    >
                        <FormControl>
                            <SelectTrigger
                                className="w-full text-black"
                                Icon={<CalendarIcon width="24" height="24" className="text-white-blue-600" />}
                            >
                                <SelectValue placeholder={<span style={{ color: '#D1D1D1' }}>{placeholder}</span>} />
                            </SelectTrigger>
                        </FormControl>
                        <SelectContent>
                            {Array.from({ length: new Date().getFullYear() - 1990 + 1 }, (_, i) => 1990 + i).map(
                                (y) => (
                                    <SelectItem key={y} value={String(y)}>
                                        {y}
                                    </SelectItem>
                                ),
                            )}
                        </SelectContent>
                    </Select>
                    <FormMessage />
                </FormItem>
            )}
        />
    );
}
