import PersonalInfo from './PersonalInfo';
import Experience from './Experience';
import JobData from './JobData';
import MainHeading from '@/components/heading/MainHeading';

import { Form } from '@/components/ui/form';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { useEffect, useMemo, useState } from 'react';
import { AddEmployeeFormValues, buildAddEmployeeSchema } from '../schemas/addEmployee/add-employee-schema';
import Submission from './Submission';
import { format } from 'date-fns';
import { Employee } from '@/types/employee.types';
import BankDetails from './BankDetails';

function apiTimeToInputValue(t: string | null | undefined): string {
    if (!t?.trim()) return '';
    const m = t.trim().match(/^(\d{1,2}):(\d{2})/);
    if (!m) return '';
    return `${m[1].padStart(2, '0')}:${m[2]}`;
}

interface Props {
    employee?: Employee | null;
}

export default function AddEmployeeForm({ employee }: Props) {
    const isEdit = Boolean(employee);
    const [error, setError] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);
    const [showSuccessPopup, setShowSuccessPopup] = useState(false);
    const [showCancelPopup, setShowCancelPopup] = useState(false);

    const schema = useMemo(() => buildAddEmployeeSchema(isEdit), [isEdit]);

    const defaultValues = useMemo(
        () => ({
            name: employee?.name || '',
            address: employee?.address || '',
            id_number: employee?.id_number || '',
            birth_date: employee?.birth_date ? new Date(employee.birth_date) : undefined,
            phone_number: employee?.phone_number || '',
            email: employee?.email || '',
            education_degree: employee?.education_degree || '',
            university: employee?.university || '',
            specialization: employee?.specialization || '',
            graduation_year: employee?.graduation_year || undefined,
            skills: employee?.skills || undefined,
            previous_experience: employee?.previous_experience || undefined,
            department_id: employee?.department_id != null ? String(employee.department_id) : '',
            position: employee?.position || '',
            branch_id: employee?.branch_id ? String(employee.branch_id) : '',
            shift_id: employee?.shift_id ? String(employee.shift_id) : '',
            start_time: apiTimeToInputValue(employee?.start_time),
            end_time: apiTimeToInputValue(employee?.end_time),
            contract_type: employee?.contract_type || '',
            password: '',
            bank_name: employee?.bank_account?.bank_name || '',
            iban_number: employee?.bank_account?.iban_number || '',
            account_name: employee?.bank_account?.account_name || '',
            account_number: employee?.bank_account?.account_number || '',
            end_date: employee?.bank_account?.end_date ? new Date(employee.bank_account.end_date) : undefined,
            bank_branch: employee?.bank_account?.bank_branch || '',
            bank_address: employee?.bank_account?.bank_address || '',
            personal_image: undefined,
            degree_certificate: undefined,
            attachment: undefined,
        }),
        [employee],
    );

    const form = useForm<AddEmployeeFormValues>({
        resolver: zodResolver(schema),
        defaultValues,
    });

    useEffect(() => {
        form.reset(defaultValues);
    }, [defaultValues, form]);

    const onSubmit = async (data: AddEmployeeFormValues) => {
        setLoading(true);
        setError(null);

        const fd = new FormData();
        const appendIfDefined = (key: string, value: unknown) => {
            if (value === undefined || value === null || value === '') return;
            fd.append(key, value as string | Blob);
        };

        appendIfDefined('name', data.name);
        appendIfDefined('address', data.address);
        appendIfDefined('id_number', data.id_number);
        appendIfDefined('birth_date', format(data.birth_date, 'yyyy-MM-dd'));
        appendIfDefined('phone_number', data.phone_number);
        appendIfDefined('email', data.email);
        appendIfDefined('education_degree', data.education_degree);
        appendIfDefined('university', data.university);
        appendIfDefined('specialization', data.specialization);
        appendIfDefined('graduation_year', data.graduation_year);
        appendIfDefined('skills', data.skills);
        appendIfDefined('previous_experience', data.previous_experience);
        appendIfDefined('department_id', data.department_id);
        appendIfDefined('position', data.position);
        appendIfDefined('branch_id', data.branch_id);
        appendIfDefined('shift_id', data.shift_id);
        appendIfDefined('start_time', data.start_time);
        appendIfDefined('end_time', data.end_time);
        appendIfDefined('contract_type', data.contract_type);
        if (!isEdit || (data.password && data.password.length > 0)) {
            appendIfDefined('password', data.password);
        }

        if (data.personal_image instanceof File) fd.append('personal_image', data.personal_image);
        if (data.degree_certificate instanceof File) fd.append('degree_certificate', data.degree_certificate);
        if (data.attachment instanceof File) fd.append('attachment', data.attachment);

        appendIfDefined('bank_name', data.bank_name);
        appendIfDefined('iban_number', data.iban_number);
        appendIfDefined('account_name', data.account_name);
        appendIfDefined('account_number', data.account_number);
        if (data.end_date) appendIfDefined('end_date', format(data.end_date, 'yyyy-MM-dd'));
        appendIfDefined('bank_branch', data.bank_branch);
        appendIfDefined('bank_address', data.bank_address);

        try {
            await apiPost({
                endpoint: employee ? endpoints.employee.update + employee.id : endpoints.employee.create,
                body: fd as unknown as Record<string, unknown>,
            });
            setShowSuccessPopup(true);
        } catch (error: unknown) {
            const err = error as { response?: { data?: { errors?: Record<string, string[]>; msg?: string } }; request?: unknown };
            if (err.response?.data?.errors) {
                Object.entries(err.response.data.errors).forEach(([field, messages]) => {
                    form.setError(field as keyof AddEmployeeFormValues, {
                        type: 'manual',
                        message: messages.join(', '),
                    });
                });
            } else {
                let errorMessage = 'حدث خطأ أثناء إرسال البيانات. يرجى المحاولة مرة أخرى.';
                if (err.response) {
                    errorMessage = err.response.data?.msg || errorMessage;
                } else if (err.request) {
                    errorMessage = 'تعذر الاتصال بالخادم. يرجى التحقق من اتصالك بالإنترنت.';
                }
                setError(errorMessage);
            }
        } finally {
            setLoading(false);
        }
    };

    return (
        <>
            <Form {...form}>
                <form onSubmit={form.handleSubmit(onSubmit)} className="mb-8">
                    {error && (
                        <div className="mb-4 p-4 bg-red-100 border border-red-400 text-red-700 rounded-lg">
                            <div className="flex justify-between items-center">
                                <span className="">{error}</span>
                                <button type="button" onClick={() => setError(null)} className="text-red-700 hover:text-red-900">
                                    ×
                                </button>
                            </div>
                        </div>
                    )}
                    <div>
                        <MainHeading text="البيانات الشخصية" />
                        <PersonalInfo image={employee?.personal_image} isEdit={isEdit} />
                        <MainHeading text="المؤهلات والخبرات" />
                        <Experience image={employee?.degree_certificate} />
                        <MainHeading text="البيانات الوظيفية" />
                        <JobData image={employee?.attachment} />
                        <MainHeading text="تفاصيل الحساب البنكي" />
                        <BankDetails />
                    </div>
                    <Submission
                        employee={employee}
                        loading={loading}
                        setShowCancelPopup={setShowCancelPopup}
                        setShowSuccessPopup={setShowSuccessPopup}
                        showCancelPopup={showCancelPopup}
                        showSuccessPopup={showSuccessPopup}
                    />
                </form>
            </Form>
        </>
    );
}
