import { z } from 'zod';

const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB
const ALLOWED_FILE_TYPES = ['image/jpeg', 'image/png', 'image/jpg', 'image/gif', 'image/svg+xml'];

export const addEmployeeBaseSchema = z.object({
    name: z.string().min(1, 'Name is required'),
    address: z.string().min(1, 'Address is required'),
    id_number: z.string().min(1, 'The personal id number field is required.'),
    birth_date: z.optional(z.date()),
    phone_number: z
        .string()
        .min(1, 'رقم الهاتف مطلوب')
        .refine((val) => /^\d+$/.test(val), 'الرجاء إدخال أرقام فقط')
        .refine((val) => val.length >= 8 && val.length <= 15, 'يجب أن يتكون رقم الهاتف من 8 إلى 15 رقم'),
    email: z.string().min(1, 'The email field is required.').email('Please enter a valid email address.'),
    personal_image: z
        .instanceof(File)
        .refine((file) => file.size <= MAX_FILE_SIZE, `Image must be less than ${MAX_FILE_SIZE}MB`)
        .refine(
            (file) => ALLOWED_FILE_TYPES.includes(file.type),
            'Only .jpeg, .png, .jpg, .gif, and .svg formats are allowed',
        )
        .optional()
        .nullable(),
    education_degree: z.string().min(1, 'Education degree is required'),
    university: z.string().optional().nullable(),
    specialization: z.string().min(1, 'Spexialization is required'),
    graduation_year: z.string({
        required_error: 'Graduation year is required',
    }),
    skills: z.string().optional().nullable(),
    previous_experience: z.string().optional().nullable(),
    degree_certificate: z
        .instanceof(File)
        .refine((file) => file.size <= MAX_FILE_SIZE, `Image must be less than ${MAX_FILE_SIZE}MB`)
        .refine(
            (file) => ALLOWED_FILE_TYPES.includes(file.type),
            'Only .jpeg, .png, .jpg, .gif, and .svg formats are allowed',
        )
        .optional()
        .nullable(),
    department_id: z.string().min(1, 'Department is required'),
    position: z.string().min(1, 'Position name is required'),
    branch_id: z.string().min(1, 'Branch is required'),
    contract_type: z.string().min(1, 'Contract type is required'),
    shift_id: z.string().min(1, 'Shift is required'),
    start_time: z.string().optional(),
    end_time: z.string().optional(),
    attachment: z
        .instanceof(File)
        .refine((file) => file.size <= MAX_FILE_SIZE, `Image must be less than ${MAX_FILE_SIZE}MB`)
        .refine(
            (file) => ALLOWED_FILE_TYPES.includes(file.type),
            'Only .jpeg, .png, .jpg, .gif, and .svg formats are allowed',
        )
        .optional()
        .nullable(),
    password: z.string().optional().default(''),

    bank_name: z.string().optional().nullable(),
    iban_number: z.string().optional().nullable(),
    account_name: z.string().optional().nullable(),
    account_number: z.string().optional().nullable(),
    end_date: z.date().optional().nullable(),
    bank_branch: z.string().optional().nullable(),
    bank_address: z.string().optional().nullable(),
});

export type AddEmployeeFormValues = z.infer<typeof addEmployeeBaseSchema>;

export function buildAddEmployeeSchema(isEdit: boolean) {
    return addEmployeeBaseSchema.superRefine((data, ctx) => {
        if (!isEdit) {
            if (!data.password || data.password.length < 6) {
                ctx.addIssue({
                    code: z.ZodIssueCode.custom,
                    message: 'Password must be at least 6 characters',
                    path: ['password'],
                });
            }
        } else if (data.password && data.password.length > 0 && data.password.length < 6) {
            ctx.addIssue({
                code: z.ZodIssueCode.custom,
                message: 'Password must be at least 6 characters',
                path: ['password'],
            });
        }
    });
}
