import SelectInputForm from '@/components/forms/SelectInputForm';
import SmallImgInputForm from '@/components/forms/SmallImgInputForm';
import TextInputForm from '@/components/forms/TextInputForm';
import YearSelectForm from '@/components/forms/YearSelectForm';

interface Props {
    image: string | null | undefined;
}

export default function Experience({ image }: Props) {
    return (
        <div className="mb-6 grid grid-cols-1 md:grid-cols-[1fr_1fr_164px] gap-6">
            <div className='flex flex-col gap-3'>
                <SelectInputForm
                    name="education_degree"
                    label="درجة الشهادة"
                    options={[
                        { value: 'high_school', name: 'الثانوية العامة' },
                        { value: 'bachelor', name: 'بكالوريوس' },
                        { value: 'master', name: 'ماجستير' },
                        { value: 'phd', name: 'دكتوراه' },
                    ]}
                    placeholder="ادخل درجة الشهادة"
                />
                <TextInputForm name="specialization" label="التخصص" placeholder="ادخل التخصص" />
                <TextInputForm name="previous_experience" label="سنوات الخبره" placeholder="ادخل سنوات الخبره" type="number"/>
            </div>
            <div className='flex flex-col gap-3'>
                <TextInputForm name="university" label="الجامعة" placeholder="ادخل اسم الجامعة" />
                <YearSelectForm name="graduation_year" label="سنة التخرج" placeholder="اختر سنة التخرج" />
                <TextInputForm name="skills" label="المهارات" placeholder="ادخل المهارات" />
            </div>
            <div>
                {image ? (
                    <SmallImgInputForm
                        name="degree_certificate"
                        maxSize={10 * 1024 * 1024}
                        multiple={false}
                        label="الشهادات"
                        editImages={image}
                    />
                ) : (
                    <SmallImgInputForm
                        name="degree_certificate"
                        maxSize={10 * 1024 * 1024}
                        multiple={false}
                        label="الشهادات"
                    />
                )}
            </div>
        </div>
    );
}
