import SearchableSelectInputForm from '@/components/forms/SearchableSelectInputForm';
import SelectInputForm from '@/components/forms/SelectInputForm';
import SmallImgInputForm from '@/components/forms/SmallImgInputForm';
import TextInputForm from '@/components/forms/TextInputForm';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { Branch } from '@/types/branches.types';
import { Department } from '@/types/department.types';
import { useEffect, useMemo, useState } from 'react';
import { useFormContext } from 'react-hook-form';
import { shiftInfo } from '../../types/shift.types';
import TimeInputForm from '@/components/forms/TimeInputForm';

/** Normalize API time strings (e.g. `09:00:00`) for HTML `input type="time"`. */
function apiTimeToInputValue(t: string | null | undefined): string {
    if (!t?.trim()) return '';
    const m = t.trim().match(/^(\d{1,2}):(\d{2})/);
    if (!m) return '';
    return `${m[1].padStart(2, '0')}:${m[2]}`;
}

interface Props {
    image: string | null | undefined;
}

export default function JobData({ image }: Props) {
    const { setValue, watch } = useFormContext();
    const shiftId = watch('shift_id');

    const [branches, setBranches] = useState<{ name: string; value: string }[]>([]);
    const [branchesError, setBranchesError] = useState<string | null>(null);

    const [departments, setDepartments] = useState<{ name: string; value: string }[]>([]);
    const [departmentsError, setDepartmentsError] = useState<string | null>(null);

    useEffect(() => {
        const fetchDepartments = async () => {
            try {
                const response = await apiGet({
                    endpoint: endpoints.departments.list,
                    queryParams: { page: 1, pageSize: 200 },
                });
                const rows: Department[] = response.data?.data?.data ?? [];
                const list = Array.isArray(rows) ? rows : [];
                const options = list
                    .filter((d) => d.is_active !== false)
                    .map((d) => ({ name: d.name, value: String(d.id) }));
                setDepartments(options);
                setDepartmentsError(null);
            } catch {
                setDepartments([]);
                setDepartmentsError('تعذر تحميل الأقسام.');
            }
        };
        fetchDepartments();
    }, []);

    useEffect(() => {
        const fetchBranches = async () => {
            try {
                const response = await apiGet({ endpoint: endpoints.branch.list });

                const options = response.data.data.data.map((branch: Branch) => {
                    return { name: branch.name, value: String(branch.id) };
                });
                setBranches(options);
                setBranchesError(null);
            } catch (error) {
                setBranchesError('Error fetching branches. Please try again later.');
            }
        };

        fetchBranches();
    }, []);

    const [shiftRecords, setShiftRecords] = useState<shiftInfo[]>([]);
    const [shiftsError, setShiftsError] = useState<string | null>(null);

    const shifts = useMemo(
        () => shiftRecords.map((s) => ({ name: s.name, value: String(s.id) })),
        [shiftRecords],
    );

    const shiftsById = useMemo(
        () => Object.fromEntries(shiftRecords.map((s) => [String(s.id), s])) as Record<string, shiftInfo>,
        [shiftRecords],
    );

    useEffect(() => {
        const fetchShifts = async () => {
            try {
                const response = await apiGet({ endpoint: endpoints.shifts.list });
                const rows: shiftInfo[] = response.data.data;
                setShiftRecords(Array.isArray(rows) ? rows : []);
                setShiftsError(null);
            } catch (error) {
                setShiftsError('Error fetching shifts. Please try again later.');
            }
        };

        fetchShifts();
    }, []);

    useEffect(() => {
        if (!shiftId) return;
        const shift = shiftsById[shiftId];
        if (!shift) return;
        const opts = { shouldDirty: false, shouldValidate: false };
        setValue('start_time', apiTimeToInputValue(shift.shift_start_time), opts);
        setValue('end_time', apiTimeToInputValue(shift.shift_end_time), opts);
    }, [shiftId, shiftsById, setValue]);

    return (
        <div className="mb-6 grid grid-cols-1 md:grid-cols-[1fr_1fr_164px] gap-6">
            <div className='flex flex-col gap-3'>
                {/* <TextInputForm name="employee_number" label="كود الموظف" placeholder="ادخل كود الموظف" /> */}
                <SelectInputForm
                    name="department_id"
                    label="القسم"
                    options={departments}
                    placeholder="اختر القسم"
                    error={departmentsError}
                    data={true}
                />
                {/* <TextInputForm name="employee_degree" label="الدرجة الوظيفية" placeholder="ادخل الدرجة الوظيفية" /> */}

                <SelectInputForm
                    name="shift_id"
                    label="الورديات"
                    options={shifts}
                    placeholder="اختر الوردية"
                    error={shiftsError}
                    data={true}
                />
                <TimeInputForm name="start_time" label="وقت بداية الدوام" placeholder="HH:MM" />
            </div>
            <div className='flex flex-col gap-3'>
                <SelectInputForm
                    name="position"
                    label="الوظيفة"
                    options={[
                        { value: 'manager', name: 'مدير' },
                        { value: 'employee', name: 'موظف' },
                        { value: 'intern', name: 'تدريبي' },
                    ]}
                    placeholder="اختر الوظيفة"
                />
                <SearchableSelectInputForm
                    name="branch_id"
                    label="الفرع"
                    placeholder="اختر الفرع"
                    options={branches}
                    error={branchesError}
                    data={true}
                />
                <SelectInputForm
                    name="contract_type"
                    label="نوع التعاقد"
                    options={[
                        { value: 'full_time', name: 'دوام كامل' },
                        { value: 'part_time', name: 'دوام جزئي' },
                    ]}
                    placeholder="ادخل نوع التعاقد"
                />
                <TimeInputForm name="end_time" label="وقت انتهاء الدوام" placeholder="HH:MM" />


            </div>
            <div>
                {image ? (
                    <SmallImgInputForm
                        name="attachment"
                        maxSize={10 * 1024 * 1024}
                        multiple={false}
                        label="الشهادات"
                        editImages={image}
                    />
                ) : (
                    <SmallImgInputForm name="attachment" maxSize={10 * 1024 * 1024} multiple={false} label="الشهادات" />
                )}
            </div>
        </div>
    );
}
